import React from 'react';
import PostItem from './PostItem';
import './PostList.css';

const PostList = ({ posts, loading, onEdit, onDelete }) => {
  if (loading && posts.length === 0) {
    return (
      <div className="loading-container">
        <div className="loading-spinner" aria-hidden="true"></div>
        <p>Loading posts...</p>
      </div>
    );
  }

  if (posts.length === 0) {
    return (
      <section className="post-list-section fade-in" aria-labelledby="posts-heading">
        <div className="empty-state">
          <svg className="empty-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 20H5a2 2 0 01-2-2V6a2 2 0 012-2h10a2 2 0 012 2v1m2 13a2 2 0 01-2-2V7m2 13a2 2 0 002-2V9a2 2 0 00-2-2h-2m-4-3H9M7 16h6M7 8h6v4H7V8z" />
          </svg>
          <h3 id="posts-heading" className="empty-title">No posts yet</h3>
          <p className="empty-description">Create your first blog post using the form above to get started.</p>
        </div>
      </section>
    );
  }

  return (
    <section className="post-list-section fade-in" aria-labelledby="posts-heading">
      <header className="list-header">
        <h2 id="posts-heading" className="list-title">All Posts</h2>
        <span className="post-count">{posts.length} {posts.length === 1 ? 'post' : 'posts'}</span>
      </header>

      <div className="posts-grid" role="list">
        {posts.map(post => (
          <PostItem
            key={post._id}
            post={post}
            onEdit={onEdit}
            onDelete={onDelete}
          />
        ))}
      </div>
    </section>
  );
};

export default PostList;
